contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount) public payable {
        require(address(this).balance >= amount);
        uint beforeBalance = address(c).balance;
        bool reverted;
        // first drain any pre-existing balance via a successful zero-value call is unnecessary;
        // attempt the go() call with the given amount
        try c.go{value: amount}() {
            reverted = false;
            // successful go() forwards everything and sweeps the rest out
            assert(address(c).balance <= beforeBalance);
        } catch {
            reverted = true;
        }
        if (reverted) {
            assert(address(c).balance == beforeBalance);
        } else {
            assert(true);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint extra) public payable {
        require(address(this).balance >= amount + extra);
        // First give c some pre-existing balance via its payable fallback.
        (bool okFb, ) = address(c).call{value: extra}("");
        require(okFb);
        // Deciding call: go() must forward the value and sweep ALL remaining balance to the owner.
        c.go{value: amount}();
        assert(address(c).balance == 0);
    }

    receive() external payable {}
}

