contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint deposit) public payable {
        require(true);
        require(address(this).balance >= deposit);
        address ownerBefore = c.owner();
        uint balBefore = address(c).balance;
        // fund the test contract's ability to send by forwarding from our balance via c's go with 0 not needed;
        // deposit ether into c through its fallback as a top-level call
        (bool okDeposit, ) = address(c).call{value: deposit}("");
        require(okDeposit);
        uint afterDeposit = address(c).balance;
        // now call go() with zero value; it should forward 0 to target and transfer the whole balance to owner
        bool reverted;
        try c.go{value: 0}() { reverted = false; } catch { reverted = true; }
        assert(
            (reverted && address(c).balance == afterDeposit && c.owner() == ownerBefore)
            || (!reverted && address(c).balance == 0 && c.owner() == ownerBefore && balBefore + deposit >= 0)
        );
    }
    receive() external payable {}
}

